from browser_validation import *
click('Render','tab');run('scroll','down',900,'--selector','#panelScroll');snap()
a=state();run('download','#exportBtn',str(ROOT/'horizon-session-export.json'));payload=json.loads((ROOT/'horizon-session-export.json').read_text());check('session JSON export',payload['version']==1 and payload['settings']==a['d']['settings'],{'version':payload['version'],'camera':payload['camera'],'time':payload['time']})
run('download','#captureBtn',str(ROOT/'captured-observation.png'));check('PNG view capture',(ROOT/'captured-observation.png').read_bytes().startswith(b'\x89PNG\r\n\x1a\n'),{'bytes':(ROOT/'captured-observation.png').stat().st_size,'renderSize':a['d']['internalSize']})
click('Environment','tab');range_to('mass',1.7);changed=state();click('Render','tab');run('scroll','down',900,'--selector','#panelScroll');click('Import session');run('upload','#importFile',str(ROOT/'horizon-session-export.json'));restored=state();shot('session-import-success.png');check('import restores actual settings and observer',restored['d']['settings']==payload['settings'] and restored['d']['camera']==payload['camera'] and changed['d']['settings']['mass']!=restored['d']['settings']['mass'],{'modifiedMass':changed['d']['settings']['mass'],'restoredMass':restored['d']['settings']['mass'],'time':restored['d']['time']})
(ROOT/'invalid-session.json').write_text('{"version":1,"settings":{"mass":"bad"},"camera":{"target":[0,0,0]}}')
run('upload','#importFile',str(ROOT/'invalid-session.json'));bad=state();msg=ev('document.getElementById("toast").textContent');shot('invalid-session-error.png');check('invalid import rejects without changing scene',msg.startswith('Import failed:') and bad['d']['settings']==restored['d']['settings'],msg)
run('reload');run('wait','--fn','Horizon.diagnostics.ready && Horizon.diagnostics.frames>1');reload=state();check('direct-file local persistence',reload['d']['settings']==restored['d']['settings'] and reload['d']['camera']==restored['d']['camera'] and reload['d']['paused']==restored['d']['paused'],{'beforeCamera':restored['d']['camera'],'afterCamera':reload['d']['camera'],'paused':reload['d']['paused']})
# A reproducible camera continuity check with time explicitly frozen and no recording context reset.
click('Render','tab');run('uncheck','#taa');click('Orbit camera');base=state();run('mouse','move',440,350);run('mouse','down');samples=[]
for x,y in [(455,360),(475,375),(500,390)]:run('mouse','move',x,y);samples.append(state())
run('mouse','up');shot('paused-camera-continuity.png');check('paused orbit continuity isolates lensing from animation',len({s['p']['hash'] for s in samples})==3 and all(s['d']['time']==base['d']['time'] and s['d']['paused'] for s in samples),[{'hash':s['p']['hash'],'time':s['d']['time'],'camera':s['d']['camera']} for s in samples])
# Expose the actual evolving field at a fixed off-axis ray, including paths that loop.
click('Classic');run('wait','--fn','Math.abs(Horizon.diagnostics.camera.pitch-.18)<.001');click('Environment','tab');range_to('spin',0);click('Render','tab');range_to('maxSteps',512);range_to('step',.3)
scan=ev('(()=>{let best=null;for(let i=0;i<300;i++){let x=.175+i*.00015,r=Horizon.traceRay(x,.04);if(!best||r.bend>best.bend)best={x,y:.04,state:r.state,steps:r.steps,bend:r.bend,nearest:r.nearest,energyDrift:r.energyDrift,hits:r.hits};}return best})()');check('photon-region paths have complex turning',scan['bend']>180 and scan['steps']>70,scan)
x=round((scan['x']+1)*964/2);y=round(72+(1-scan['y'])*626/2);click('Inspect a ray');run('mouse','move',x,y);run('mouse','down');run('mouse','up');run('select','#viewMode','2');shot('photon-sphere-ray.png');check('photon-region selection via pointer',ev('Horizon.diagnostics.selectedRay.steps')>50,ev('Horizon.diagnostics.selectedRay'))
